# Code generated by Claude
"""Monitors of the MPVI pipeline: they watch the run and LOG (the drop monitor also decides, see below) (design plan 8; docs/mpvi_decisions.md).

    monitor = make_drop_monitor(model, oracle_checker, "left")
    entries = monitor["tick"](obs, events, segment)          # called by the orchestrator every tick; events = [(event, segment), ...] of this tick; new log entries come back

Drop monitor: from the pick's "gripper_closed" event until the next "gripper_opened" event (the object is held, lifted and carried: the fingers are commanded closed all that time) it reports
"dropped" once when the fingers close further than the held object's width allows (since 2026-10-21 the monitor DECIDES: the orchestrator fails the current step on a "dropped" entry that has "decides": True, which starts the retry path; M044. PICK_PLACE_CFG["drop_monitor_decides"]): the finger opening has stayed more than PICK_PLACE_CFG["drop_margin_m"] below the opening measured at
the grasp (the width of what was held) for PICK_PLACE_CFG["drop_dwell_s"]. It uses only what the real robot has: the gripper's measured finger opening (obs["joint_angles"]) and the
commanded state (known from the events); no object pose. An effort (current) drop is NOT modelled: the simulator has no gripper effort readback the real robot would match. The log entry has the time, the
finger opening, the width held and, beside it, the sim oracle's "held?" verdict at that tick (ground truth, for the log only, never an input of the monitor).

Contents:
    make_drop_monitor(model, oracle_checker, side, cfg).
"""

from src.robot_helpers import arm_ids
from src.task_config import PICK_PLACE_CFG


def make_drop_monitor(model, oracle_checker, side="left", cfg=PICK_PLACE_CFG, decides=None):
    """Builds the drop monitor.

    Args:
        model (mujoco.MjModel): The task model (only to find the finger joint's index in the joint angles).
        oracle_checker (dict): The sim oracle (make_oracle_checker): its pick check gives the "held?" verdict logged beside a drop.
        side (str): The gripper's arm. Defaults to "left".
        cfg (dict): PICK_PLACE_CFG ("drop_margin_m", "drop_dwell_s", "drop_monitor_decides"). Defaults to it.
        decides (bool or None): Whether a "dropped" entry fails the step (the orchestrator acts on entry["decides"]). Defaults to cfg["drop_monitor_decides"].

    Returns:
        dict: {"name": "drop monitor", "tick": tick(obs, events, segment) -> list of new log entries, "log": the entries so far, "report": () -> {"log"}}.
    """
    fq = int(model.jnt_qposadr[arm_ids(model, side)["finger_jnt"][0]])
    decides = cfg.get("drop_monitor_decides", True) if decides is None else bool(decides)
    S = {"armed": False, "width": None, "seg": None, "below_since": None, "fired": False, "log": []}

    def tick(obs, events, segment=None):
        new = []
        try:
            t = float(obs["time"])
            travel = float(obs["joint_angles"][fq])
            for ev, seg in events:
                if ev == "gripper_closed":
                    S.update(armed=True, width=travel, seg=seg, below_since=None, fired=False)
                elif ev == "gripper_opened":
                    S["armed"] = False
            if S["armed"] and not S["fired"]:
                if travel < S["width"] - cfg["drop_margin_m"]:
                    S["below_since"] = t if S["below_since"] is None else S["below_since"]
                    if t - S["below_since"] >= cfg["drop_dwell_s"]:
                        held = oracle_checker["check"](S["seg"], "drop_monitor", obs)
                        entry = {"kind": "dropped", "decides": decides, "time": t, "below_since": S["below_since"], "finger_opening_m": travel, "held_width_m": S["width"], "oracle_held": bool(held["passed"]),
                                 "oracle_reason": held["reason"]}
                        S["fired"] = True
                        S["log"].append(entry)
                        new.append(entry)
                else:
                    S["below_since"] = None
        except Exception as e:                                      # noqa: BLE001 - a monitor only logs: its own failure is logged and never stops the run
            entry = {"kind": "monitor_error", "time": obs.get("time"), "error": f"{type(e).__name__}: {e}"}
            S["log"].append(entry)
            new.append(entry)
        return new

    return {"name": "drop monitor", "tick": tick, "log": S["log"], "report": lambda: {"log": list(S["log"])}}
